// ========================================================
// FILTRO RIGOROSO DE EVENTOS DA EVOLUTION API
// Só processa mensagens novas reais (messages.upsert)
// Descarta: updates de leitura, entrega, reações, grupos e fromMe
// ========================================================

const body = $input.first().json.body || $input.first().json;
const event = body.event;
if (event !== 'messages.upsert') return [];

const data = body.data || {};
const key = data.key || {};
if (key.fromMe === true) return [];

const remoteJid = key.remoteJid || '';
if (!remoteJid || remoteJid.includes('@g.us') || remoteJid.includes('status@broadcast')) return [];

const phone = remoteJid.split('@')[0].replace(/\D/g, '');
const provider_message_id = String(key.id || '');
if (!phone || !/^[A-Za-z0-9_-]{6,255}$/.test(provider_message_id)) return [];

const pushName = data.pushName || '';
const message = data.message || {};
const messageType = data.messageType || '';

if (messageType === 'reactionMessage' || messageType === 'stickerMessage') return [];

const isAudio = messageType === 'audioMessage' || !!message.audioMessage;
let textContent = '';

if (isAudio) {
  textContent = '[AUDIO]';
} else if (messageType === 'conversation') {
  textContent = message.conversation || '';
} else if (messageType === 'extendedTextMessage') {
  textContent = message.extendedTextMessage?.text || '';
} else if (messageType === 'imageMessage') {
  textContent = message.imageMessage?.caption || '';
} else if (messageType === 'documentMessage') {
  textContent = message.documentMessage?.fileName || '';
} else if (messageType === 'locationMessage') {
  const loc = message.locationMessage || {};
  textContent = `[LOCALIZACAO: ${loc.degreesLatitude}, ${loc.degreesLongitude}]`;
}

if (!isAudio && (!textContent || textContent.trim().length <= 1)) return [];

return [{
  json: {
    body,
    phone,
    provider_message_id,
    pushName,
    message: textContent.trim(),
    isAudio,
    instance: body.instance || 'Sound',
    timestamp: new Date().toISOString()
  }
}];

const data = $input.first().json.body.data;
const instance = $input.first().json.body.instance || 'Sound';

return [{
  json: {
    instance,
    requestBody: {
      message: {
        key: data.key,
        message: data.message
      },
      convertToMp4: false
    }
  }
}];

const base64 = $input.first().json.base64 || '';
const buffer = Buffer.from(base64, 'base64');

return [{
  json: {},
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'audio/ogg',
      fileName: 'audio.ogg',
      fileExtension: 'ogg'
    }
  }
}];

const webhookData = $('Code in JavaScript').first().json;
const transcribedText = $input.first().json.text || '';

return [{
  json: {
    phone: webhookData.phone,
    provider_message_id: webhookData.provider_message_id,
    pushName: webhookData.pushName || '',
    message: transcribedText.trim(),
    instance: webhookData.instance || 'Sound',
    timestamp: new Date().toISOString(),
    isAudio: true
  }
}];

const input = $input.first().json;

return [{
  json: {
    phone: input.phone,
    provider_message_id: input.provider_message_id,
    pushName: input.pushName || '',
    message: input.message.trim(),
    instance: input.instance || 'Sound',
    timestamp: input.timestamp || new Date().toISOString(),
    isAudio: false
  }
}];

const item = $input.first().json;
return [{
  json: {
    chatInput: item.message,
    phone: item.phone,
    pushName: item.pushName || '',
    instance: item.instance || 'Sound',
    provider_message_id: item.provider_message_id || '',
    message: item.message,
    isAudio: item.isAudio || false,
    timestamp: item.timestamp || new Date().toISOString()
  }
}];

const rows = $('Coletar Pendentes').all();
const ctx = $('Normalizar Entrada WhatsApp').first().json;

const mergedMessage = rows.map(r => r.json.message).filter(Boolean).join(' ').trim();
const ids = rows.map(r => r.json.id);

return [{
  json: {
    ...ctx,
    chatInput: mergedMessage || ctx.chatInput,
    merged_message: mergedMessage || ctx.chatInput,
    buffer_ids: ids,
    message_count: ids.length
  }
}];

// Recupera os dados consolidados do lead e mensagem atual
const inputData = $('Consolidar Dados do Lead').first().json;
const currentMsg = inputData.chatInput || inputData.merged_message || '';
const phone = inputData.phone || '';
const pushName = inputData.pushName || '';
const instance = inputData.instance || 'Sound';
const infoLeadTexto = inputData.infoLeadTexto || '';
const leadConhecido = inputData.leadConhecido || false;
const dadosLead = inputData.dadosLead || {};

// Recupera o histórico do nó Carregar Histórico (Memory Manager)
const historyItems = $input.all();
let historyLines = [];

for (const item of historyItems) {
  const json = item.json || item;

  if (Array.isArray(json.messages)) {
    for (const msg of json.messages) {
      if (msg.human) historyLines.push(`[Usuário]: ${msg.human.trim()}`);
      if (msg.ai) historyLines.push(`[Flávio (Sound)]: ${msg.ai.trim()}`);
      if (msg.role && msg.content) {
        const sender = (msg.role === 'user' || msg.role === 'human') ? 'Usuário' : 'Flávio (Sound)';
        historyLines.push(`[${sender}]: ${msg.content.trim()}`);
      }
    }
  } else if (json.text) {
    const sender = (json.sender === 'user' || json.sender === 'human') ? 'Usuário' : 'Flávio (Sound)';
    historyLines.push(`[${sender}]: ${json.text.trim()}`);
  }
}

const historyText = historyLines.length > 0 ? historyLines.join('\n') : '(Início da conversa, nenhuma mensagem anterior)';

const contextoParaRoteador = [
  'CADASTRO DO LEAD (NOCODB):',
  infoLeadTexto,
  '',
  'HISTÓRICO DA CONVERSA:',
  historyText,
  '',
  'MENSAGEM ATUAL DO USUÁRIO:',
  currentMsg
].join('\n');

return [{
  json: {
    chatInput: currentMsg,
    phone: phone,
    pushName: pushName,
    instance: instance,
    historyText: historyText,
    infoLeadTexto: infoLeadTexto,
    leadConhecido: leadConhecido,
    leadId: inputData.leadId,
    dadosLead: dadosLead,
    contextoParaRoteador: contextoParaRoteador
  }
}];

const raw = $input.first().json.text || $input.first().json.output || '';
const prep = $('Preparar Contexto').first().json;

let originalInput = prep.chatInput || '';
let phone = prep.phone || '';
let pushName = prep.pushName || '';
let historyText = prep.historyText || '';
let instance = prep.instance || 'Sound';
let infoLeadTexto = prep.infoLeadTexto || '';
let leadConhecido = prep.leadConhecido || false;
let leadId = prep.leadId || null;
let dadosLead = prep.dadosLead || {};

let perfil = 'TRIAGEM';

// Se o lead já tiver perfil conhecido no cadastro do NocoDB, prioriza o perfil oficial
if (leadConhecido && dadosLead['Tipo Empresa']) {
  const tipo = String(dadosLead['Tipo Empresa']).toLowerCase();
  if (tipo.includes('distribuidor') || tipo.includes('revenda') || tipo.includes('cooperativa')) {
    perfil = 'CAN';
  } else if (tipo.includes('representante') || tipo.includes('rtv') || tipo.includes('autônomo')) {
    perfil = 'RTV';
  }
}

// Caso contrário, avalia o roteamento da LLM
if (perfil === 'TRIAGEM') {
  try {
    const clean = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(clean);
    if (parsed.perfil) perfil = parsed.perfil.toUpperCase();
  } catch (e) {
    if (/\bPRO\b/i.test(raw)) perfil = 'PRO';
    else if (/\bCAN\b/i.test(raw)) perfil = 'CAN';
    else if (/\bRTV\b/i.test(raw)) perfil = 'RTV';
    else if (/\bFOR_NDI\b|\bFOR\b|\bNDI\b/i.test(raw)) perfil = 'FOR_NDI';
  }
}

const promptParaAgente = [
  'INFORMAÇÕES DE CADASTRO DO LEAD:',
  infoLeadTexto,
  '',
  'HISTÓRICO DA CONVERSA:',
  historyText,
  '',
  'MENSAGEM ATUAL DO CLIENTE:',
  originalInput
].join('\n');

return [{
  json: {
    chatInput: originalInput,
    perfil: perfil,
    phone: phone,
    pushName: pushName,
    historyText: historyText,
    instance: instance,
    infoLeadTexto: infoLeadTexto,
    leadConhecido: leadConhecido,
    leadId: leadId,
    dadosLead: dadosLead,
    promptParaAgente: promptParaAgente
  }
}];

const output = ($input.first().json.output || '').trim();
const inputData = $('Consolidar Dados do Lead').first().json;
const phone = inputData.phone || '';
const instance = inputData.instance || 'Sound';
const leadId = inputData.leadId || null;
const leadConhecido = inputData.leadConhecido || false;
const dadosLead = inputData.dadosLead || {};

if (!output) return [];

// Checa tags de sistema
const sendPdfMilho = output.includes('[ENVIAR_PDF_MILHO]');
const handoffRealizado = output.includes('[HANDOFF_COMERCIAL]');

// Limpa tags do texto que o cliente vai ler no WhatsApp
let cleanOutput = output
  .replace(/\[ENVIAR_PDF_MILHO\]/gi, '')
  .replace(/\[HANDOFF_COMERCIAL\]/gi, '')
  .trim();

// Quebra inteligente em até 2 bolhas para não poluir o WhatsApp com blocos gigantes
let rawParts = cleanOutput.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
let bubbles = [];

if (rawParts.length >= 2) {
  if (rawParts.length === 2) {
    bubbles = rawParts;
  } else {
    const last = rawParts.pop();
    bubbles = [rawParts.join('\n\n'), last];
  }
} else if (cleanOutput.length > 250 && cleanOutput.includes('?')) {
  const lastQ = cleanOutput.lastIndexOf('?');
  const textBefore = cleanOutput.substring(0, lastQ);
  const lastDot = Math.max(textBefore.lastIndexOf('. '), textBefore.lastIndexOf('.\n'));
  if (lastDot > 50) {
    bubbles = [
      cleanOutput.substring(0, lastDot + 1).trim(),
      cleanOutput.substring(lastDot + 1).trim()
    ];
  } else {
    bubbles = [cleanOutput];
  }
} else {
  bubbles = [cleanOutput];
}

bubbles = bubbles.slice(0, 2);

return [{
  json: {
    phone,
    instance,
    bubbles,
    send_pdf_milho: sendPdfMilho,
    handoff_realizado: handoffRealizado,
    leadId,
    leadConhecido,
    dadosLead,
    respostaAgente: cleanOutput
  }
}];

const texto = $json.bubbles || $json.output || '';
const delay = Math.min(4000, Math.max(1200, Math.floor(texto.length / 35) * 1000));
const phone = $('Montar merged_message').first().json.phone;
const instance = $('Montar merged_message').first().json.instance || 'Sound';

return [{
  json: {
    phone,
    instance,
    output: texto,
    delay_ms: delay
  }
}];

