DELETE FROM message_buffer WHERE phone = '{{ $json.phone }}';
DELETE FROM sound_n8n_chat_histories WHERE session_id = '{{ $json.phone }}';
DO $$
BEGIN
  IF EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'sound_contacts') THEN
    DELETE FROM sound_handoffs WHERE contact_id IN (SELECT id FROM sound_contacts WHERE phone = '{{ $json.phone }}');
    DELETE FROM sound_tags WHERE contact_id IN (SELECT id FROM sound_contacts WHERE phone = '{{ $json.phone }}');
    DELETE FROM sound_messages WHERE phone = '{{ $json.phone }}';
    DELETE FROM sound_conversations WHERE phone = '{{ $json.phone }}';
    DELETE FROM sound_contacts WHERE phone = '{{ $json.phone }}';
  END IF;
END $$;

