const merged = $('Montar merged_message').first().json;
const nocoData = $input.first().json || {};
const nocoList = Array.isArray(nocoData.list) ? nocoData.list : [];
const lead = nocoList.length > 0 ? nocoList[0] : null;

let infoLeadTexto = '';
let leadConhecido = false;

if (lead) {
  leadConhecido = true;
  infoLeadTexto = [
    'DADOS JÁ CONHECIDOS DO CADASTRO (NÃO PERGUNTE NOVAMENTE):',
    `- Nome: ${lead.Nome || 'Não informado'}`,
    `- Empresa: ${lead['Nome da Empresa'] || 'Não informado'}`,
    `- Cidade/Estado: ${lead.Cidade || ''} - ${lead.Estado || ''}`,
    `- Tipo de Atuação: ${lead['Tipo Empresa'] || 'Não informado'}`,
    `- Culturas atendidas: ${lead.Cultura || 'Não informado'}`,
    `- Produtores atendidos: ${lead.qtd_produtores || 'Não informado'}`,
    `- Equipe de campo: ${lead.equipe || 'Não informado'}`,
    `- Experiência com biológicos: ${lead.comercializacao_atual || 'Não informado'}`,
    `- Momento da empresa: ${lead.momento_empresa || 'Não informado'}`,
    `- É o decisor: ${lead.responsavel_portfolio || 'Não informado'}`,
    `- E-mail: ${lead.Email || 'Não informado'}`,
    `- Classificação: ${lead.Classificacao || 'Não informado'} (${lead.Pontuacao || 0} pts)`,
    `- Status no CRM: ${lead.Status_Lead || 'Novo'}`,
    'REGRA MANDATÓRIA: Trate o cliente pelo Nome conhecido e cite a Empresa dele. NUNCA pergunte nada que já conste nessa ficha! Avance direto para entender o interesse no TRIGGER ou tirar dúvidas.'
  ].join('\n');
} else {
  infoLeadTexto = '(Lead novo, ainda sem cadastro prévio no CRM/NocoDB)';
}

return [{
  json: {
    ...merged,
    leadConhecido,
    leadId: lead ? (lead.Id || lead.id) : null,
    dadosLead: lead || {},
    infoLeadTexto
  }
}];

const formatData = $('Formatar Partes WhatsApp').first().json;
const consLead = $('Consolidar Dados do Lead').first().json;
const lead = consLead.dadosLead || {};
const phone = consLead.phone || '';
const pushName = consLead.pushName || '';
const handoff = formatData.handoff_realizado || false;

// Determina status
let statusLead = lead.Status_Lead || 'Em Contato';
if (handoff) {
  statusLead = 'Handoff Comercial';
} else if (statusLead === 'Novo') {
  statusLead = 'Em Contato';
}

const payload = {
  Nome: lead.Nome || pushName || 'Lead WhatsApp',
  'Nome da Empresa': lead['Nome da Empresa'] || '',
  Cidade: lead.Cidade || '',
  Estado: lead.Estado || '',
  'Tipo Empresa': lead['Tipo Empresa'] || 'canal/revenda',
  Cultura: lead.Cultura || 'Soja/Milho',
  qtd_produtores: lead.qtd_produtores || '',
  equipe: lead.equipe || '',
  comercializacao_atual: lead.comercializacao_atual || '',
  momento_empresa: lead.momento_empresa || '',
  responsavel_portfolio: lead.responsavel_portfolio || 'sou o responsável pela decisão',
  WhatsApp: lead.WhatsApp || ('+' + phone),
  Email: lead.Email || '',
  Classificacao: lead.Classificacao || (handoff ? 'Quente' : 'Morno'),
  Status_Lead: statusLead
};

return [{
  json: {
    leadId: consLead.leadId,
    leadExiste: consLead.leadConhecido,
    handoff: handoff,
    phone: phone,
    statusLead: statusLead,
    payload: payload,
    resumoHandoff: `*🤝 Handoff Comercial Realizado!*\n\n*Nome:* ${payload.Nome}\n*Empresa:* ${payload['Nome da Empresa'] || 'Não informada'}\n*WhatsApp:* ${payload.WhatsApp}\n*Local:* ${payload.Cidade} - ${payload.Estado}\n*Status:* ${statusLead}\n*Última Mensagem do Flávio:* ${formatData.respostaAgente}`
  }
}];

